-- Generated by tk/scripts/build_energy_base_raw_from_cdf.py (nodes)
SELECT
    cast(`key` AS STRING) AS externalId
  , CASE WHEN `cost` IS NOT NULL AND trim(cast(`cost` AS STRING)) != '' THEN cast(`cost` AS LONG) ELSE NULL END AS `cost`
  , cast(`costUnit` AS STRING) AS `costUnit`
  , CASE WHEN `coverage` IS NOT NULL AND trim(cast(`coverage` AS STRING)) != '' THEN cast(`coverage` AS DOUBLE) ELSE NULL END AS `coverage`
  , cast(`currentRisk` AS STRING) AS `currentRisk`
  , cast(`futureRisk` AS STRING) AS `futureRisk`
  , cast(`inspectionEffectiveness` AS STRING) AS `inspectionEffectiveness`
  , CASE WHEN `latestDeadline` IS NOT NULL AND trim(cast(`latestDeadline` AS STRING)) != '' THEN to_timestamp(`latestDeadline`) ELSE NULL END AS `latestDeadline`
  , cast(`ndeMethod` AS STRING) AS `ndeMethod`
  , cast(`timeframe` AS STRING) AS `timeframe`
FROM `{{energyBaseRawDb}}`.`InspectionRecommendation`
